INSERT INTO "albums" VALUES(69,'Capacity','Big Thief','美国',NULL,'Indie Rock, Indie Folk, Folk Rock','0.0','Capacity is the second studio album by the American band Big Thief, released through Saddle Creek Records on June 9, 2017.',0,NULL,'Saddle Creek','/covers/69-Big Thief-Capacity.jpg','37:38',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,2017,'Folk,Rock',NULL,21,NULL,NULL,3.66,0,'',8.3,'https://pitchfork.com/reviews/albums/23280-capacity/','6650e857-be48-475a-984b-704e492f4cef','active');
