INSERT INTO "albums" VALUES(253,'A-Sides','Adrianne Lenker & Buck Meek','美国','印第安纳波利斯','Singer-Songwriter, Indie Folk',NULL,'A-Sides is a greatest hits album by the American rock band Soundgarden with songs spanning the band''s thirteen-year career. It was released on November 4, 1997, through A&M Records.',NULL,'2024-12-19','独立发行','/covers/253-Adrianne Lenker & Buck Meek-A-Sides.jpg','43:51',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2014,'Folk',NULL,5,137,3,NULL,NULL,NULL,NULL,NULL,'3918afc1-1abb-4a9f-aedc-e2c9b2ed1d02','active');
