INSERT INTO "albums" VALUES(280,'爱情多恼河','熊天平','中国','台湾','Mandopop',NULL,'《爱情多恼河》是熊天平于1997年发行的首张录音室专辑，共收录12首歌曲，由袁惟仁、刘天健、徐德昌、黄国伦担任制作人。1997年，专辑同名曲《爱情多恼河》获得第四届全球华语音乐榜中榜“中文Top20榜中榜歌曲”奖。',0,'2014-03-12','上华','/covers/280-熊天平-爱情多恼河.jpg','54:36',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1997,'Pop',NULL,241,2,2,NULL,NULL,NULL,NULL,NULL,'7d3c07f3-cb17-49b3-9772-930091780a0f','active');
