INSERT INTO "albums" VALUES(370,'3','Carsick Cars','中国','大陆','Indie Rock, Noise Pop, Jangle Pop','3.36','3 (three) is a number, numeral and digit. It is the natural number following 2 and preceding 4, and is the smallest odd prime number and the only prime preceding a square number.',0,'2025-09-16','兵马司唱片','/covers/370-Carsick Cars-3.jpg','53:48',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2014,'Rock,Pop',NULL,34,197,17,NULL,NULL,NULL,NULL,NULL,'7c5737c4-9ceb-41e6-807e-9aaf27849f8c','active');
