INSERT INTO "albums" VALUES(494,'The Mountain','Gorillaz','美国',NULL,'Electronic','0.0','The Mountain (title written in Devanagari as पर्वत, parvata, "mountain" in Sanskrit) is the ninth studio album by British virtual band Gorillaz. It was released on 27 February 2026 through their own label, Kong, with distribution by Sony Music subsidiary the Orchard. It is the first Gorillaz album to be released without the participation of Parlophone.
INSERT INTO "albums" VALUES(495,'The Apple Tree Under the Sea','Hemlocke Springs','美国',NULL,'Electronic','0.0','The Apple Tree Under the Sea (stylized in lowercase) is the debut studio album by American singer and songwriter Hemlocke Springs, released independently on February 13, 2026.',0,NULL,'AWAL Recordings','/covers/495-Hemlocke Springs-The Apple Tree Under the Sea.jpg','33:15',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,3.52,2026,'Alt-Pop',NULL,66,NULL,NULL,3.5,0,'',NULL,NULL,'42bcad2d-ff06-4ff3-9b8a-f41d8b1d10de','active');
