INSERT INTO "albums" VALUES(565,'De Todas las Flores','Natalia Lafourcade',NULL,NULL,NULL,NULL,'墨西哥创作歌手Natalia Lafourcade 2022年专辑，拉丁格莱美获奖作品，融合bolero、son jarocho、ranchera等拉美传统音乐流派。全西班牙语，以花为意象贯穿12首曲目，同期录音追求现场感。Metacritic 92/100，Pitchfork 8.6 BNM。',0,NULL,NULL,'/covers/unknown-Natalia-Lafourcade-De-Todas-las-Flores.jpg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2022,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'22f502bb-631f-4b4c-8e53-c1b7cdf3c959','active');
