INSERT INTO "albums" VALUES(567,'Dance Of Love','Tucker Zimmerman',NULL,NULL,NULL,NULL,'Tucker Zimmerman, the Belgium-based/US-born octogenarian folk singer-songwriter, collaborates with Big Thief (Adrianne Lenker) on this 4AD release. A tender, wordly-wise meditation on love in all its forms — romantic, familial, and spiritual — recorded with the full Big Thief band plus Iji and Twain.',0,NULL,'4AD','/covers/567-Tucker Zimmerman-Dance Of Love.jpg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2024,NULL,NULL,321,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'active');
INSERT INTO "albums" VALUES(568,'想念式','苏醒',NULL,NULL,NULL,NULL,'苏醒首张个人创作专辑，2010年发行，收录10首歌曲，其中7首为苏醒完整创作。R&B/Hip-Hop风格，获第八届东南劲爆音乐榜金曲奖。',0,NULL,'Sony Music','/covers/568-苏醒-想念式.jpg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2010,NULL,NULL,322,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'active');
INSERT INTO "albums" VALUES(569,'Sister','Sonic Youth',NULL,NULL,NULL,NULL,'Sonic Youth 1987年经典专辑，被广泛认为是乐队最佳作品之一。Noise Rock/Alternative Rock风格，影响深远，Pitchfork等媒体均给予极高评价。',0,NULL,'SST Records','/covers/569-Sonic Youth-Sister.jpg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1987,NULL,NULL,131,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'active');
