INSERT INTO "albums_2025" VALUES(351,'堕落天使','郑智化','中国','台湾','Mandopop, Pop Rock',3.75,'郑智化1990年发行的代表作之一，融合流行摇滚与抒情元素，展现其对青春、信仰与社会的深刻反思。专辑风格鲜明，歌词富有哲理性与批判性，是台湾流行音乐黄金年代的重要作品。',0,'2025-08-21',8,'可登有声','covers/351-郑智化-堕落天使.jpg','41:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1990-11-01','Pop',NULL);
INSERT INTO "albums_2025" VALUES(353,'You Can Listen, You Can Talk','Carsick Cars','中国','大陆','Indie Rock, Noise Rock, Neo-Psychedelia, Shoegaze, Jangle Pop',3.13,'Carsick Cars于2009年发行的第二张录音室专辑，延续其噪音摇滚与迷幻流行的风格，整体音色更为成熟与细腻。专辑中融合中英文歌词，展现出中国独立音乐在国际语境中的探索与表达。',0,'2025-08-21',3,'兵马司唱片','covers/353-Carsick_Cars-You_Can_Listen,_You_Can_Talk.jpg','53:53:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2009-06-26','Rock',NULL);
